pub(super) fn create() -> Vec<RecipeMeta> {
    SPECIAL_RECIPES
        .iter()
        .map(|record| {
            let start = record.material_start;
            let end = start + record.material_len;

            RecipeMeta {
                result: record.result,
                materials: MATERIALS[start..end].to_vec(),
                is_special: true,
            }
        })
        .collect()
}
